{
  "hooks": {
    "PreToolUse": [
      {
        "_ai_specs_managed": "ai-specs:hooks:plan-build-flow:plan-build-gate",
        "hooks": [
          {
            "command": "export AI_SPECS_PROJECT_ROOT=\"$CLAUDE_PROJECT_DIR\"; export AI_SPECS_HOOK_AGENT=claude; cli='<INSTALL>/dist/ai-specs'; [ -x \"$cli\" ] || cli=ai-specs; command -v \"$cli\" >/dev/null 2>&1 || exit 0; exec \"$cli\" plan-build-gate",
            "type": "command"
          }
        ],
        "matcher": "Edit|Write|MultiEdit|NotebookEdit"
      }
    ]
  }
}
